# Run from the package root after 63_land_only_report.R:  Rscript data-raw/qa/70_land_section.R
# Writes the section "Land-only shapes" of data-raw/known_issues.md (between <!-- land:start --> and <!-- land:end -->) from the results of 63_land_only_report.R. Every number is read from them.
source("data-raw/qa/helpers.R"); source("data-raw/dat/exposure_functions.R", local = TRUE); suppressMessages(library(dplyr))
L <- readRDS("data-raw/dat/fetch/exposure_summary_tables.rds")$blocks
R <- readRDS(qa_out("63_land_report.rds")); Z <- R$zcta; B <- R$blocks$by_vint
f0 <- function(x) format(round(x), big.mark = ",", scientific = FALSE, trim = TRUE); pc <- function(x, d = 2) sprintf(paste0("%.", d, "f%%"), 100 * x); fx <- function(x, d = 4) formatC(x, format = "f", digits = d)
md <- function(df) { df[] <- lapply(df, as.character); paste(c(paste0("| ", paste(names(df), collapse = " | "), " |"), paste0("|", paste(rep("---", ncol(df)), collapse = "|"), "|"), apply(df, 1, function(r) paste0("| ", paste(r, collapse = " | "), " |"))), collapse = "\n") }
zt <- do.call(rbind, lapply(names(Z), function(v) { z <- Z[[v]]; data.frame(`Boundary year` = v, ZCTAs = f0(z$zctas), `With a water polygon inside` = f0(z$water_touched), `Ratio, 1st percentile` = fx(z$quantiles[3]), `Ratio, median` = fx(z$quantiles[5], 7), `Ratio, 99th percentile` = fx(z$quantiles[7], 7), `Smallest ratio` = fx(z$quantiles[1], 3), `Within 1%` = pc(z$within1), `Within 5%` = pc(z$within5), `Within 10%` = pc(z$within10), `More than 1% apart` = f0(z$over1), check.names = FALSE) }))
bt <- do.call(rbind, lapply(names(B), function(v) { b <- B[[v]]; data.frame(`Boundary year` = v, `Blocks of the tracts reached` = f0(b$blocks), `Median ratio` = fx(b$quantiles[5], 7), `Within 1%` = pc(b$within1), `Within 5%` = pc(b$within5), `Within 10%` = pc(b$within10), `More than 1% apart` = f0(b$over1), `More than 10% apart` = f0(b$over10), `No Census land, land shape above 0` = f0(b$aland_zero_land_positive), `Land shape zero, residents above 0` = f0(b$land_zero_with_residents), check.names = FALSE) }))
w20 <- Z[["2020"]]$worst; worst <- data.frame(ZCTA = w20$ZCTA, `Census land area (m2)` = f0(round(w20$ALAND)), `Land-only shape (m2)` = f0(round(w20$land_m2)), Ratio = fx(w20$ratio, 3), check.names = FALSE)
wa <- do.call(rbind, lapply(names(Z), function(v) { x <- readRDS(sprintf("data-raw/cache/zcta_land_%s.rds", v))$d; x <- x[x$ALAND > 0 & abs(x$land_m2 / x$ALAND - 1) > 0.01, c("ZCTA", "ALAND", "land_m2")]; x$vintage <- as.integer(v); x$ratio <- x$land_m2 / x$ALAND; x[order(x$vintage, x$ratio), ] }))
write.csv(wa, qa_out("land_zcta_over1pct.csv"), row.names = FALSE)
txt <- c("<!-- land:start -->", "## Land-only shapes", "",
 "Areas that are shares of a unit (the DAT area shares of `tornado_exposure`, `dat_exposure_tract` and `dat_exposure_blockgroup`) use land-only shapes: the unit polygon minus the Census water polygons (TIGER/Line AREAWATER, one file per county; TIGER2020 for the 2020 boundary year and TIGER2010 for the 2010 and 2000 boundary years, `data-raw/provenance_water.csv`) that lie inside it, computed in EPSG:5070 (`data-raw/land_functions.R`). Nothing is simplified or rounded: a land-only shape is the unit polygon with the part inside a water polygon removed. Invalid polygons are repaired with `st_make_valid()` and counted below.", "",
 paste0("**ZCTAs against the Census land area (`ALAND`).** The ratio is the area of the land-only shape divided by `ALAND`, for every ZCTA of each boundary year (", f0(Z[["2020"]]$water_files), " water files, ", f0(round(Z[["2020"]]$water_bytes / 1e6)), " MB for 2020; ", f0(Z[["2010"]]$water_files), " files, ", f0(round(Z[["2010"]]$water_bytes / 1e6)), " MB for 2010 and 2000; ", f0(Z[["2020"]]$water_polygons), " and ", f0(Z[["2010"]]$water_polygons), " water polygons, of which ", f0(Z[["2020"]]$water_invalid_repaired + Z[["2010"]]$water_invalid_repaired), " were invalid and repaired; the ZCTA polygons repaired: ", paste(names(Z), vapply(Z, function(z) z$polygons_invalid_repaired, 0), sep = ": ", collapse = ", "), "):"), "", md(zt), "",
 paste0("The land-only shape reproduces `ALAND` for ", pc(Z[["2020"]]$within1), " of the 2020 ZCTAs within 1%. The ZCTAs that differ by more than 1% (", f0(sum(vapply(Z, function(z) z$over1, 0))), " in all three boundary years, listed in `data-raw/qa/out/land_zcta_over1pct.csv`) are those where the Census counts water-feature area as land (dry lakes, tidal and coastal areas) or the reverse. The 20 largest differences in the 2020 boundary year:"), "", md(worst), "",
 paste0("**Blocks against the block land area.** The same ratio for every block of the census tracts that the DAT footprints reach (the blocks of the tracts and block groups tables; the ratio is the land-only shape divided by the block's `ALAND`):"), "", md(bt), "",
 paste0("**Rule.** Residents are allocated by the share of each block's land-only shape that a footprint zone covers (people live on land), because the land-only block shape reproduces the block `ALAND` within 1% for ", pc(R$blocks$within1), " of these blocks and within 5% for ", pc(R$blocks$within5), ". The area shares of tracts and block groups divide by the sum of the land-only shapes of their blocks (the blocks of a tract or block group are the blocks with the same GEOID prefix)."), "",
 paste0("**Blocks with no land.** A block whose land-only shape has an area of at most ", format(land_tolerance_m2, scientific = FALSE), " square meters is treated as having no land: the subtraction leaves floating-point residue where a block boundary and a water boundary coincide (the largest residue is ", format(L[["largest_land_residue_m2"]], digits = 3), " square meters; the smallest land-only shape of a block with Census land area is ", format(R$blocks$min_land_shape_m2, digits = 3), " square meters). ", f0(L[["blocks_no_land"]]), " of the ", f0(L[["blocks_in_tracts"]]), " blocks of the tracts the footprints reach have no land, ", f0(L[["no_land_but_aland_positive"]]), " of them with a Census land area above 0. ", f0(L[["blocks_no_land_with_residents"]]), " of them hold residents (", f0(L[["residents_in_no_land_blocks"]]), " residents): these are allocated by the share of the block polygon that a zone covers (", f0(L[["polygon_pieces_for_residents"]]), " zone-block pieces, ", sprintf("%.1f", L[["residents_by_polygon_share"]]), " residents in all). They take no part in the area shares."),
 "<!-- land:end -->")
kl <- readLines("data-raw/known_issues.md"); a <- grep("<!-- land:start -->", kl, fixed = TRUE); b <- grep("<!-- land:end -->", kl, fixed = TRUE)
kl <- if (length(a) && length(b)) c(kl[seq_len(a - 1)], txt, kl[-seq_len(b)]) else append(kl, c(txt, ""), after = grep("<!-- dat-exposure:start -->|<!-- dat:start -->", kl)[1] - 1)
writeLines(kl, "data-raw/known_issues.md"); cat(txt, sep = "\n")
